{"file_text": "<nav aria-label="Application progress" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between p-0 m-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < CurrentStep;
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep;

            <li class="text-center flex-fill position-relative">
                <button type="button"
                        class="btn btn-link text-decoration-none p-0 w-100 @(isFuture ? "disabled" : "")"
                        disabled="@isFuture"
                        @onclick="() => OnStepClicked.InvokeAsync(step)">
                    <div class="d-flex flex-column align-items-center">
                        <span class="rounded-circle d-inline-flex align-items-center justify-content-center mb-1
                            @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-secondary text-white")"
                              style="width:36px;height:36px;font-size:0.9rem;">
                            @if (isCompleted)
