@page "/apply"
@using sv_948e308a59df4f929cdfd9bf8fd8758a.Models
@using sv_948e308a59df4f929cdfd9bf8fd8758a.Services
@rendermode InteractiveServer
@inject IApplicationService AppService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width:800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (_submittedId is not null)
    {
        <div class="alert alert-success text-center py-5">
            <h3>Application Submitted!</h3>
            <p class="lead">Your application ID is <strong>#@_submittedId</strong>.</p>
            <p>We will review your application and get back to you shortly.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep" OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 1:
                <PersonalInfoStep Model="_personal"
                                  ApplicationService="AppService"
                                  OnNext="NextStep" />
                break;
            case 2:
                <WorkHistoryStep Entries="_workEntries"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 3:
                <ReferencesStep References="_references"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 4:
                <CoverLetterStep @bind-CoverLetter="_coverLetter"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 5:
                <ReviewStep Personal="_personal"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="_coverLetter"
                            IsSubmitting="_isSubmitting"
                            OnSubmit="SubmitApplication"
                            OnBack="PreviousStep"
                            OnEditStep="GoToStep" />
                break;
        }
    }
</div>

@code {
    private int _currentStep = 1;
    private bool _isSubmitting;
    private int? _submittedId;

    private readonly PersonalInfoModel _personal = new();
    private readonly List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
    private readonly List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
    private string _coverLetter = "";

    private void NextStep() => _currentStep++;

    private void PreviousStep() => _currentStep--;

    private void GoToStep(int step)
    {
        if (step < _currentStep)
            _currentStep = step;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        try
        {
            var application = new JobApplication(
                _personal.ToRecord(),
                new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
                _references.Select(r => r.ToRecord()).ToList(),
                _coverLetter);

            _submittedId = await AppService.SubmitApplicationAsync(application);
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

